{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Brexpiprazole, a close structural analogue sharing the same 4-(piperazin-1-yl)butoxy-quinolinone scaffold, has an absolute oral bioavailability of 95% in humans, strongly supporting a high F classification for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ziprasidone, another aryl-piperazine antipsychotic with a fused lactam core, showed an absolute oral bioavailability of 59% in healthy men, which is well above the 20% threshold and supports high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Trazodone, an aryl-piperazine antidepressant with a similar alkyl-piperazine linker, had absolute systemic availability averaging 70-90% across subject groups, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Urapidil, an aryl-piperazine drug, had an absolute systemic bioavailability of 78% (72-84%) in healthy volunteers, providing additional support for high bioavailability in this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is aripiprazole, and the closest structural analogue brexpiprazole has 95% absolute oral bioavailability. Other aryl-piperazine antipsychotics and related drugs show oral bioavailability values of 59-91%, all clearly above the 20% threshold. No affirmative evidence supports low bioavailability for this scaffold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for aripiprazole itself is present in the provided evidence.",
    "Food effects and specific formulation effects on the query molecule were not directly assessed.",
    "First-pass metabolism of the query was not directly measured, though close analogues indicate limited first-pass loss."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

